/**
 * stageTemplate — the declarative description of a lamina's stage.
 *
 * A stage is an artwork plus a set of placeholders.  The artwork is static; a
 * placeholder is a rectangle with a pivot and a *binding* saying which model
 * quantity drives it and through which animator.  Nothing here knows it is
 * describing a heart — swap the template and the same renderer draws a
 * different lamina.
 *
 * The template is fetched at runtime rather than imported, so the bindings can
 * be edited without a rebuild.  Geometry is generated by
 * `tools/cut_heart_layers.py`; labels and bindings are hand-written and the
 * tool preserves them.
 */

export type EnvelopeId = 'ventricular' | 'atrial'

/** One additive contribution to a placeholder's scale, gated by a phase window. */
export interface MotionTerm {
  envelope: EnvelopeId
  amount: number
}

/**
 * Scales a motion by a live model quantity.  `reference` is the value at which
 * the gain is 1× — 70 mL of stroke volume leaves the artwork at its drawn size.
 */
export interface Modulator {
  attribute: string
  reference: number
  range: [number, number]
}

export interface Motion {
  animator: string
  terms: MotionTerm[]
  /** null = amplitude is a declared constant, because no model output fits. */
  modulator: Modulator | null
}

export interface Flow {
  animator: string
  rateFrom: string
  colour: string
  particles: number
  radius: number
}

/**
 * A phase window, anchored at one end and given a duration in seconds.
 * Converting seconds to a phase fraction needs the live cycle length, which is
 * the point: ejection time shrinks with rate far more slowly than the cycle
 * does, so systole takes a larger share of a fast beat.
 */
export interface EnvelopeSpec {
  /** Anchor. Exactly one of these. */
  startFraction?: number
  endFraction?: number
  /** Duration in seconds from a model attribute … */
  durationFrom?: string
  /** … or a declared constant, for windows the model cannot describe yet. */
  duration?: number
}

export function resolveEnvelope(
  spec: EnvelopeSpec,
  cycleSeconds: number,
  values: Record<string, number>
): [number, number] {
  const seconds = spec.durationFrom ? values[spec.durationFrom] : spec.duration
  const safeCycle = cycleSeconds > 0.05 ? cycleSeconds : 1
  const len = Math.min(0.9, Math.max(0.02, (seconds ?? 0.3) / safeCycle))
  if (spec.endFraction !== undefined) return [spec.endFraction - len, spec.endFraction]
  return [spec.startFraction ?? 0, (spec.startFraction ?? 0) + len]
}

export interface PlaceholderGeometry {
  x: number
  y: number
  w: number
  h: number
  /** Scale pivot: cavity centroid, or vessel root for the great vessels. */
  px: number
  py: number
  /** Great vessels only: centreline from the root outward. */
  path?: [number, number][]
}

export interface Placeholder {
  label: string
  asset: string
  geometry: PlaceholderGeometry
  motion?: Motion
  flow?: Flow
}

export interface StageTemplate {
  laminaId: string
  artwork: { src: string; width: number; height: number }
  /**
   * Where beat timing comes from.  `bind` names the attribute holding cycle
   * length in seconds; each envelope's *duration* is likewise a model
   * attribute in seconds where one exists, so a phase window is a real
   * interval rather than a fixed share of the cycle.
   */
  rhythm: {
    bind: string
    envelopes: Record<EnvelopeId, EnvelopeSpec>
  }
  /** Painter's order — later entries draw on top. */
  drawOrder: string[]
  placeholders: Record<string, Placeholder>
}

/** Where a bound quantity came from, which is what Lee's rule is about. */
export type Provenance = 'model' | 'sensor' | 'constant' | 'missing'

export interface BindingRow {
  channel: 'timing' | 'envelope' | 'amplitude' | 'flow'
  attribute: string | null
  provenance: Provenance
  /**
   * Owned by the stage rather than the placeholder.  Beat timing is one
   * binding that every placeholder reads, so it is reported once at stage
   * level instead of turning all six frames the same colour.
   */
  shared?: boolean
}

export function provenanceOf(attribute: string, sources: Record<string, string>): Provenance {
  const s = sources[attribute]
  if (s === 'PRELIMINARY') return 'model'
  if (s === 'SENSOR') return 'sensor'
  return 'missing'
}

/**
 * The stage-wide beat bindings: cycle length, plus each phase window whose
 * duration the model supplies.  Windows the model cannot describe report as
 * constants rather than passing silently.
 */
export function describeRhythm(
  template: StageTemplate,
  sources: Record<string, string>
): BindingRow[] {
  const rows: BindingRow[] = [
    {
      channel: 'timing',
      attribute: template.rhythm.bind,
      provenance: provenanceOf(template.rhythm.bind, sources),
      shared: true,
    },
  ]
  for (const spec of Object.values(template.rhythm.envelopes)) {
    rows.push({
      channel: 'envelope',
      attribute: spec.durationFrom ?? null,
      provenance: spec.durationFrom ? provenanceOf(spec.durationFrom, sources) : 'constant',
      shared: true,
    })
  }
  return rows
}

/**
 * Describe every channel of one placeholder: what drives it and whether that
 * source is allowed to. `sources` comes from the lamina schema, so this is the
 * model's own classification rather than a second opinion held by the UI.
 */
export function describeBindings(
  place: Placeholder,
  template: StageTemplate,
  sources: Record<string, string>
): BindingRow[] {
  const rows: BindingRow[] = []
  if (place.motion) {
    rows.push(...describeRhythm(template, sources))
    const mod = place.motion.modulator
    rows.push({
      channel: 'amplitude',
      attribute: mod?.attribute ?? null,
      provenance: mod ? provenanceOf(mod.attribute, sources) : 'constant',
    })
  }
  if (place.flow) {
    rows.push({
      channel: 'flow',
      attribute: place.flow.rateFrom,
      provenance: provenanceOf(place.flow.rateFrom, sources),
    })
  }
  return rows
}

/**
 * Count every distinct binding on the stage by where its data comes from.
 *
 * Shared bindings — beat timing, which drives all six placeholders — are
 * counted once, so the tally reads as "how many distinct things drive this
 * stage" rather than multiplying one violation by six.
 *
 * Lives here rather than in the overlay because the count is a property of the
 * template, not of one way of drawing it: the showcase view reports the same
 * numbers as the schematic, which is the point of reporting them at all.
 */
export function tallyProvenance(
  template: StageTemplate,
  sources: Record<string, string>
): { tally: Record<Provenance, number>; total: number } {
  const tally: Record<Provenance, number> = { model: 0, sensor: 0, constant: 0, missing: 0 }
  for (const row of describeRhythm(template, sources)) tally[row.provenance]++
  for (const id of template.drawOrder) {
    const place = template.placeholders[id]
    if (!place) continue
    for (const row of describeBindings(place, template, sources)) {
      if (!row.shared) tally[row.provenance]++
    }
  }
  return { tally, total: tally.model + tally.sensor + tally.constant + tally.missing }
}

/**
 * Placeholders whose amplitude is a declared constant, with their labels.
 *
 * These are the regions the model has nothing to say about — currently both
 * atria, because no model output describes an atrium.  Naming them is the
 * point: an unbound region that quietly keeps moving is indistinguishable from
 * a bound one, and a viewer has no way to tell which parts of the picture are
 * carrying information.
 */
export function constantRegions(
  template: StageTemplate,
  sources: Record<string, string>
): { id: string; label: string }[] {
  const out: { id: string; label: string }[] = []
  for (const id of template.drawOrder) {
    const place = template.placeholders[id]
    if (!place) continue
    const own = describeBindings(place, template, sources).filter((r) => !r.shared)
    if (own.length > 0 && own.every((r) => r.provenance === 'constant')) {
      out.push({ id, label: place.label })
    }
  }
  return out
}

/** Resolved template plus the base URL its assets are relative to. */
export interface LoadedStage {
  template: StageTemplate
  assetUrl: (file: string) => string
}

export async function loadStage(dir: string): Promise<LoadedStage> {
  const base = `${import.meta.env.BASE_URL}${dir}/`
  const res = await fetch(`${base}template.json`)
  if (!res.ok) throw new Error(`stage template ${dir}: ${res.status}`)
  return { template: await res.json(), assetUrl: (file) => `${base}${file}` }
}

/** Point at fraction `u` ∈ [0,1] along a polyline, linearly interpolated. */
export function alongPath(path: [number, number][], u: number): [number, number] {
  const t = Math.min(0.9999, Math.max(0, u)) * (path.length - 1)
  const i = Math.floor(t)
  const f = t - i
  const a = path[i]
  const b = path[i + 1] ?? a
  return [a[0] + (b[0] - a[0]) * f, a[1] + (b[1] - a[1]) * f]
}
